    C c;
    constructor() { c = new C(address(this), 0); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint256 diff) public {
        require(diff > 0);
        c.AdjustDifficulty(diff); if (__ESBMC_reverted()) return;
        c.OpenToThePublic(); if (__ESBMC_reverted()) return;
        bool reverted;
        c.play(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert(reverted && !c.hasPlayerWagered(address(this)));
    }
    receive() external payable {}
}

