pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PoCGame c;

    function setUp() public {
        c = new PoCGame(address(this), 0);
    }

    function _run(uint256 diff) internal {
        vm.assume(diff > 0);
        try c.AdjustDifficulty(diff) {} catch { return; }
        try c.OpenToThePublic() {} catch { return; }
        bool reverted;
        try c.play() { reverted = false; } catch { reverted = true; }
        assertTrue(reverted && !c.hasPlayerWagered(address(this)));
    }

    function testFuzz_run(uint256 diff) public {
        _run(diff);
    }

    receive() external payable {}
}
